// DataImpulse (https://docs.dataimpulse.com): a plan comes with sticky ports on one gateway, and the
// user API rotates the IP behind one. Needs DATAIMPULSE_LOGIN and DATAIMPULSE_PASSWORD in the
// command environment; DATAIMPULSE_COUNTRY (a two-letter code) and DATAIMPULSE_PORT are optional.
const login = env.DATAIMPULSE_LOGIN;
const password = env.DATAIMPULSE_PASSWORD;
if (!login || !password) {
    throw new Error("Set DATAIMPULSE_LOGIN and DATAIMPULSE_PASSWORD in the command environment");
}

const HOST = "gw.dataimpulse.com";
const FIRST_PORT = 10000;
const LAST_PORT = 20000;
const country = env.DATAIMPULSE_COUNTRY ? String(env.DATAIMPULSE_COUNTRY).toLowerCase() : null;

// The country rides on the login rather than on the port, so it costs the forum nothing to name one
const write = (port) => {
    const user = country ? login + "__cr." + country : login;
    chan.setProxy("http://" + encodeURIComponent(user) + ":" + encodeURIComponent(password) +
        "@" + HOST + ":" + port);
};

const current = chan.getProxy();
const match = current && current.indexOf(HOST) >= 0 ? current.match(/:(\d+)$/) : null;
const held = match ? Number(match[1]) : 0;
if (held < FIRST_PORT || held > LAST_PORT) {
    // Not on a sticky port of this gateway yet, so putting the forum on one is the change to make
    const port = Number(env.DATAIMPULSE_PORT || FIRST_PORT);
    write(port);
    return "sticky port " + port;
}

const answer = await fetch("https://" + HOST + ":777/api/rotate_ip?port=" + held, {
    headers: { "Authorization": "Basic " + btoa(login + ":" + password) }
}).then(r => r.json());
if (answer.status !== "ok") {
    throw new Error(answer.message ||
        "DataImpulse would not change the IP (it allows one change every 30 seconds)");
}
// The credentials and the port are unchanged, but the pooled connections still have to go
write(held);
return "sticky port " + held + " · changed";
